import React from 'react';
import {Controller, useFormContext} from 'react-hook-form';
import {View} from 'react-native';
import TextFieldCM from '../../../../../../../components/TextField';

type Props = {
  controlName: string;
  label: string;
  maxLength?: number;
  onPressIconRight?: () => void;
  viewIconRight?: React.ReactNode;
  multiline?: boolean;
};

const YupTextField = ({
  controlName,
  label,
  maxLength,
  onPressIconRight,
  viewIconRight,
  multiline,
}: Props) => {
  const {
    control,
    formState: {errors},
  } = useFormContext();

  return (
    <View>
      <Controller
        control={control}
        name={controlName}
        render={({field: {onChange, onBlur, value}}) => {
          return (
            <TextFieldCM
              label={label}
              placeholder={label}
              isRequired={true}
              value={value}
              onBlur={onBlur}
              onChangeText={onChange}
              onIconPress={onPressIconRight}
              maxLength={maxLength}
              errorMessage={errors[controlName]?.message as string}
              viewIconRight={viewIconRight}
              multiline={multiline}
            />
          );
        }}
      />
    </View>
  );
};

export default YupTextField;
