import React, {useState} from 'react';
import {useTranslation} from 'react-i18next';
import {Image, TouchableOpacity} from 'react-native';
import ModalUpdateAvatar from '../ModalUpdateAvatar';
import styles from './styles';
import { useAppSelector } from '../../../../hook/useRedux';
import { View as ViewCM } from 'react-native';
import { String } from '../../../../constants';
import { IconAvatarDefault, IconRoundEdit } from '../../../../assets/images';
import { SizeDP } from '../../../../constants/Size';
import TextCM from '../../../../components/Text';

const Information = () => {
  const {t} = useTranslation();
  const user = useAppSelector(state => state.account.dataAccount);

  const {firstName, lastName, email, orgName, avatar} = user;

  const [isVisibleAvatar, setIsVisibleAvatar] = useState(false);

  const toggleModalAvatar = () => {
    setIsVisibleAvatar(!isVisibleAvatar);
  };

  const getRoleName = () => {
    if (user.authorities && user.authorities.includes('ROLE_ORG_ADMIN')) {
      return t('eContract.AI.TxtAdmin');
    }
    return t('eContract.AI.TxtUser');
  };

  return (
    <ViewCM style={styles.container}>
      <ViewCM style={styles.viewAvatar}>
        {avatar ? (
          <Image
            source={{
              uri: String.PREFIX_IMG_BASE64 + avatar,
            }}
            style={styles.avatar}
          />
        ) : (
          <IconAvatarDefault width={SizeDP(64)} height={SizeDP(64)} />
        )}
        <TouchableOpacity style={styles.iconEdit} onPress={toggleModalAvatar}>
          <IconRoundEdit width={SizeDP(24)} height={SizeDP(24)} />
        </TouchableOpacity>
      </ViewCM>
      <ViewCM style={styles.viewInfo}>
        <ViewCM style={styles.viewName}>
          <TextCM style={styles.txtName} numberOfLines={1}>
            {`${firstName} ${lastName}`}
          </TextCM>
          <ViewCM style={styles.viewRole}>
            <TextCM style={styles.txtLabelRole}>{t('eContract.AI.TxtRole')}: </TextCM>
            <TextCM style={styles.txtRole}>{getRoleName()}</TextCM>
          </ViewCM>
        </ViewCM>
        <ViewCM style={styles.viewEmail}>
          <TextCM style={styles.txtLabelEmail}>{t('eContract.AI.TxtEmail')}: </TextCM>
          <TextCM style={styles.txtEmail}>{email}</TextCM>
        </ViewCM>
        <ViewCM style={styles.viewEmail}>
          <TextCM style={styles.txtLabelEmail}>{t('eContract.AI.TxtUnit')}: </TextCM>
          <TextCM style={styles.txtEmail}>{orgName}</TextCM>
        </ViewCM>
      </ViewCM>
      <ModalUpdateAvatar
        isVisible={isVisibleAvatar}
        onClose={toggleModalAvatar}
      />
    </ViewCM>
  );
};

export default Information;
