import WebView, {WebViewMessageEvent} from 'react-native-webview';
import {useNavigation} from '@react-navigation/native';
import styles from './styles';
import {SafeAreaView} from 'react-native-safe-area-context';
import {useEffect, useRef, useState} from 'react';
import {isUndefined} from 'lodash';
import {useTranslation} from 'react-i18next';
import {Keyboard, Platform} from 'react-native';
import HeaderCM from '../../../components/Header/HeaderCM';
import React from 'react';
import {NavigationName, String} from '../../../constants';
import useStoreNoti from '../store/store';
import {BASE_URL, baseSign} from '../../../services/httpClient';
import CookieManager from '@react-native-cookies/cookies';

const SignatureWebview = ({route}: any) => {
  const navigation = useNavigation<any>();
  const {t, i18n} = useTranslation();
  const webRef = useRef<WebView>(null);
  const {envelopeId, recipientId, type, userSign} = route?.params;
  // const {ekycRepository} = useAppSelector(state => state.ekyc);

  const [heightShow, setHeightShow] = useState<number>(0);

  const {reLoadDataNotification, setReloadDataNotification} = useStoreNoti();

  const [jwtToken, setJwtToken] = useState<string>('');

  useEffect(() => {
    CookieManager.get(
      `${BASE_URL}/services/envelope/api/p/envelope/${envelopeId}`,
    ).then(async cookies => {
      if (cookies && cookies[`jwttoken_${envelopeId}_${recipientId}`]) {
        setJwtToken(
          cookies[`jwttoken_${envelopeId}_${recipientId}`]?.value ?? '',
        );
      }
    });
  }, []);

  useEffect(() => {
    const sub = Keyboard.addListener('keyboardDidShow', listener => {
      setHeightShow(listener.endCoordinates.height);
    });

    const sub1 = Keyboard.addListener('keyboardDidHide', listener => {
      setHeightShow(0);
    });
    return () => {
      sub.remove();
      sub1.remove();
    };
  }, []);

  const handleOnMessage = (message: WebViewMessageEvent) => {
    const dataFromWebview = JSON.parse(message.nativeEvent.data);
    if (dataFromWebview.result === 'eContractX') {
      injectJavaScript();
    }
  };

  const handlBack = () => {
    if (!isUndefined(type) && type === 'EKYC') {
      if (isUndefined(userSign)) {
        setReloadDataNotification(!reLoadDataNotification);
        navigation.navigate(NavigationName.HomeScreen);
      } else {
        navigation.navigate(NavigationName.SignInScreen);
      }
    } else {
      navigation.goBack();
    }
  };

  const injectJavaScript = () => {
    // send success eKYC
    // if (!isUndefined(type) && type === 'EKYC') {
    //   const data = JSON.stringify({
    //     result: 'eContractX',
    //     ekyc_success: true,
    //     ekyc_details: {
    //       id: ekycRepository?.id,
    //       billCode: ekycRepository?.billCode,
    //       username: ekycRepository?.username,
    //     },
    //   });
    //   const scriptJSX = `window.postMessage('${data}', '*');`;
    //   webRef?.current?.injectJavaScript(scriptJSX);
    // }
  };

  return (
    <>
      <SafeAreaView edges={['bottom']} style={styles.ctnMain}>
        <HeaderCM
          title={t('eContract.CM.BtnBack')}
          onPressIconLeft={handlBack}
        />
        {true && (
          <WebView
            style={[Platform.OS === 'android' && {marginBottom: heightShow}]}
            onMessage={handleOnMessage}
            startInLoadingState
            sharedCookiesEnabled={true}
            thirdPartyCookiesEnabled={true}
            javaScriptEnabled={true}
            domStorageEnabled
            injectedJavaScript={String.SCRIPT_SCALE_WEBVIEW}
            allowsInlineMediaPlayback={true}
            mediaPlaybackRequiresUserAction={false}
            source={{
              uri: `${baseSign}/signing/signature-process/${envelopeId}/${recipientId}?lang=${i18n.language}&jwt=${jwtToken}`,
            }}
            ref={webRef}
            webviewDebuggingEnabled
          />
        )}
      </SafeAreaView>
    </>
  );
};

export default SignatureWebview;
