import React from 'react';
import {useTranslation} from 'react-i18next';
import {TouchableOpacity} from 'react-native';
import styles from './styles';
import { IPasswordConfig } from '../../../../../services/interface';
import TextCM from '../../../../../components/Text';
import { View as ViewCM } from 'react-native';
import SwitchCM from '../../../../../components/Switch';
import { IconBluePen } from '../../../../../assets/images';
import { SizeDP } from '../../../../../constants/Size';

interface Props {
  onPress: () => void;
  onPressSwitch: () => void;
  label: string;
  data: IPasswordConfig;
  onPressCard?: () => void;
}

const ConfigItem = ({
  onPress,
  label,
  onPressSwitch,
  data,
  onPressCard,
}: Props) => {
  const {t} = useTranslation();

  const handleOnpressCard = () => {
    if (onPressCard) {
      onPressCard();
    }
  };

  return (
    <TouchableOpacity onPress={handleOnpressCard} >
      <ViewCM style={styles.item}>
        <TextCM style={styles.txtName}>{label}</TextCM>
        <TextCM style={styles.txtEdit}>{t('eContract.GS.shareConfig.edited')}</TextCM>
        <ViewCM style={styles.viewAction}>
          <SwitchCM isEnabled={data.status} onPress={onPressSwitch} />
          <TouchableOpacity style={styles.btnEdit} onPress={onPress}>
            <IconBluePen width={SizeDP(14)} height={SizeDP(14)} />
          </TouchableOpacity>
        </ViewCM>
      </ViewCM>
    </TouchableOpacity>
  );
};

export default ConfigItem;
