import {create} from 'zustand';
import {IResponseTwoFactor} from '../../../services/interface';
import {isEmpty} from 'lodash';

interface twoFactorStore {
  twoFactor: IResponseTwoFactor;
  isReloadingSign: boolean;
  setTwoFactor: (twoFactor: IResponseTwoFactor[] | null) => void;
  setIsReloadingSign: (isReloadingSign: boolean) => void;
}

const initialSettingState = {
  twoFactor: {active: false} as IResponseTwoFactor,
  isReloadingSign: false,
};

export const useSettingStore = create<twoFactorStore>((set, get) => ({
  ...initialSettingState,
  setTwoFactor: async twoFactor => {
    try {
      const returnData = isEmpty(twoFactor)
        ? {active: false}
        : twoFactor?.find(
            item => item.type === 'two-factor' || 'two-factor-email',
          ) ?? {active: false};

      set({twoFactor: returnData});
    } catch (error) {
      throw error;
    }
  },
  setIsReloadingSign: (isReloadingSign: boolean) => {
    set({isReloadingSign: isReloadingSign});
  },
}));
