import React from 'react';
import {useTranslation} from 'react-i18next';
import {View} from 'react-native';
import {FilterType} from '../..';
import styles from './styles';
import BottomSheetCM from '../../../../../components/BottomSheet';
import GroupRadio, {GroupData} from '../../../../../components/GroupRadio';

type Props = {
  value: GroupData;
  onPicType: (value: GroupData) => void;
  lsData: {label: string; id: FilterType}[];
  isVisible: boolean;
  toggleModal: () => void;
};

const ModalPicType = ({
  value,
  onPicType,
  lsData,
  isVisible,
  toggleModal,
}: Props) => {
  const {t} = useTranslation();

  return (
    <>
      <BottomSheetCM
        renderContent={
          <ContentPicTypeView
            value={value}
            onPicType={onPicType}
            togglePicType={toggleModal}
            lsData={lsData}
          />
        }
        title={t('eContract.GS.expensesDefault.TxtPackageSelection')}
        onClose={toggleModal}
        isVisible={isVisible}
      />
    </>
  );
};

type ContentPicTypeViewProps = {
  value: GroupData;
  onPicType: (value: GroupData) => void;
  togglePicType: () => void;
  lsData: GroupData[];
};

const ContentPicTypeView = ({
  value,
  onPicType,
  togglePicType,
  lsData,
}: ContentPicTypeViewProps) => {
  const {t} = useTranslation();

  const onPressData = (value: GroupData) => {
    togglePicType();
    onPicType(value);
  };

  return (
    <View style={styles.viewPicType}>
      <GroupRadio
        data={lsData}
        onPressData={onPressData}
        currentValue={value}
        containerStyle={styles.viewGroupRadio}
      />
    </View>
  );
};

export default ModalPicType;
