import {FC, useEffect, useState} from 'react';
import {
  FlatList,
  RefreshControl,
  useWindowDimensions,
  View,
} from 'react-native';
import CardIdtemInfo from '../InfoDetail';
import {debounce, isUndefined} from 'lodash';
import styles from './styles';
import {useTranslation} from 'react-i18next';
import {
  IOrgIN,
  ISearchDTO,
  ISearchResponse,
} from '../../../../../model/interface/notification.interface';
import {useCreateNotiServices} from '../../../../../hook/apiHook/useApi';
import React from 'react';
import TextCM from '../../../../../components/Text';
import GroupRadio, {GroupData} from '../../../../../components/GroupRadio';
import {IconBlackSearch, IconGreyDownArrow} from '../../../../../assets/images';
import ButtonCM from '../../../../../components/Button';
import BottomSheetCM from '../../../../../components/BottomSheet';
import TextFieldCM from '../../../../../components/TextField';

type Props = {
  onSave?: (item: ISearchResponse) => void;
  onSelect: (item: ISearchResponse) => void;
};

const SearchComponent: FC<Props> = ({onSelect, onSave}) => {
  const [textSearch, setTextSearch] = useState<string>('');
  const [debounceSearch, setDebounceSearch] = useState<string>('');
  const [page, setPage] = useState<number>(0);
  const [totalPage, setTotalPage] = useState(1);
  const [listData, setListData] = useState<ISearchResponse[]>([]);
  const [isRefreshing, setIsRefreshing] = useState<boolean>(false);
  const [userSelected, setUserSelected] = useState<ISearchResponse>({});
  const [listOrg, setListOrg] = useState<IOrgIN[]>();
  const [valueOrg, setValueOrg] = useState<IOrgIN>();
  const [isVisible, setIsVisible] = useState<boolean>(false);
  const {t} = useTranslation();
  const {height} = useWindowDimensions();
  const NotificationServices = useCreateNotiServices();
  const debouncedSearch = debounce((text: string) => {
    setDebounceSearch(text);
  }, 500);

  useEffect(() => {
    (async () => {
      try {
        const dataResp = await NotificationServices.getAllOrgInCust();
        setListOrg(dataResp.data);
      } catch (error) {}
    })();
  }, []);

  useEffect(() => {
    setPage(0);
    debouncedSearch(textSearch);
    return () => {
      debouncedSearch.cancel();
    };
  }, [textSearch]);

  useEffect(() => {
    getData(page, 10, debounceSearch);
  }, [debounceSearch, valueOrg]);

  const getData = async (page: number, size: number, text: string) => {
    const body: ISearchDTO = {
      contactId: '',
      custId: null,
      field: '',
      from: '',
      ids: [],
      keyWord: '',
      orgIn: valueOrg?.orgIn ?? '',
      owner: '',
      q: text,
      recipientId: '',
      recipientRole: [],
      refId: '',
      terms: {},
      to: '',
      advanced: true,
      resource: 'table_user',
    };
    try {
      const listDataResp = await NotificationServices.searchUser(
        page,
        size,
        body,
      );
      setTotalPage(listDataResp.totalPage);
      const dataPrev = page === 0 ? [] : listData;
      const groupData = [...dataPrev, ...listDataResp.data].map(data => {
        return {
          ...data,
          isSelect: false,
        };
      });
      setListData(groupData);
    } catch (error) {
    } finally {
      setIsRefreshing(false);
    }
  };

  const onRefresh = () => {
    setIsRefreshing(true);
    getData(0, 10, debounceSearch);
  };
  const handleSubmit = () => {
    onSelect(userSelected);
    onSave?.(userSelected);
  };

  const onEndReached = () => {
    if (totalPage > 1 && page + 1 < totalPage) {
      getData(page + 1, 10, debounceSearch);
      setPage(page + 1);
    }
  };

  const onSelectOrg = (item: GroupData) => {
    if (item.id === 'all') {
      setValueOrg(undefined);
    } else {
      setValueOrg(listOrg?.find(org => org.id === item?.id));
    }
    setPage(0);
    setIsVisible(false);
  };

  const getCurrentValue = () => {
    if (isUndefined(valueOrg)) {
      return {id: 'all', label: t('eContract.NT.all')};
    } else {
      return {id: valueOrg.id, label: valueOrg.name};
    }
  };

  const renderListOrg = () => {
    const listOrgData =
      (listOrg?.map(org => ({
        id: org.id,
        label: org.name,
      })) as any) ?? [];
    const filterListOrg = [{id: 'all', label: t('eContract.NT.all')}, ...listOrgData];
    return (
      <>
        <TextCM style={styles.txtLabel}>{t('eContract.DC.chooseOrganization')}</TextCM>
        <GroupRadio
          data={filterListOrg as GroupData[]}
          currentValue={getCurrentValue()}
          onPressData={item => onSelectOrg(item)}
          scrollEnabled
        />
      </>
    );
  };

  return (
    <View style={{height: (height / 4) * 3}}>
      <View style={{rowGap: 10, marginBottom: 10}}>
        <TextFieldCM
          value={textSearch}
          onChangeText={setTextSearch}
          label={t('eContract.NT.fillInfo')}
          viewIconRight={<IconBlackSearch width={24} height={24} />}
        />
        <TextFieldCM
          value={isUndefined(valueOrg) ? t('eContract.NT.all') : valueOrg.name}
          onChangeText={setTextSearch}
          label={t('eContract.NT.TxtOrganization')}
          viewIconRight={<IconGreyDownArrow width={24} height={24} />}
          readOnly
          onIconPress={() => setIsVisible(true)}
          // isShowIconClear={false}
        />
      </View>
      <FlatList
        showsHorizontalScrollIndicator={false}
        showsVerticalScrollIndicator={false}
        data={listData}
        keyExtractor={(item, index) => '' + index}
        renderItem={({item}) => (
          <CardIdtemInfo
            data={item}
            onSelect={setUserSelected}
            dataSelect={userSelected}
            setListData={list => setListData(list)}
            listData={listData}
          />
        )}
        onEndReached={onEndReached}
        onEndReachedThreshold={0.5}
        refreshControl={
          <RefreshControl refreshing={isRefreshing} onRefresh={onRefresh} />
        }
      />
      <ButtonCM
        disabled={Object.keys(userSelected).length === 0}
        label={t('eContract.CM.TxtSave')}
        onPress={handleSubmit}
      />

      <BottomSheetCM
        title={t('eContract.NT.listOrg')}
        onClose={() => setIsVisible(false)}
        isVisible={isVisible}
        styleBody={{height: height / 2}}
        renderContent={renderListOrg()}
      />
    </View>
  );
};

export default SearchComponent;
