import React from 'react';
import {
  FlatList,
  TextStyle,
  TouchableOpacity,
  View,
  ViewStyle,
} from 'react-native';
import styles from './styles';
import {IcCheckbox, IcCheckboxSelect} from '../../assets/images';
import TextCM from '../Text';
import {useTranslation} from 'react-i18next';

export type GroupData = {
  id: string | number;
  label: string;
};

type Props = {
  data: GroupData[];
  currentValue?: GroupData[];
  onPressData: (item: GroupData) => void;
  containerStyle?: ViewStyle;
  itemStyle?: ViewStyle;
  labelStyle?: TextStyle;
  numColumns?: number;
  scrollEnabled?: boolean;
};
const GroupListCheck = ({
  data,
  currentValue = [],
  onPressData,
  containerStyle,
  itemStyle,
  labelStyle,
  numColumns = 1,
  scrollEnabled = false,
}: Props) => {
  const {t} = useTranslation();
  const checkSelected = (item: GroupData) => {
    return currentValue.some(i => i.id === item.id);
  };

  const onPressItem = (item: GroupData) => {
    onPressData(item);
  };

  const renderItem = ({item}: {item: GroupData}) => {
    return (
      <TouchableOpacity
        key={item.id}
        style={[styles.viewItem, itemStyle]}
        onPress={() => {
          onPressItem(item);
        }}>
        {checkSelected(item) ? (
          <IcCheckboxSelect width={24} height={24} />
        ) : (
          <IcCheckbox width={24} height={24} />
        )}
        <TextCM style={[styles.txtName, labelStyle]}>{t(item.label)}</TextCM>
      </TouchableOpacity>
    );
  };

  return (
    <View style={[styles.container, containerStyle]}>
      <FlatList
        data={data}
        keyExtractor={item => item.id.toString()}
        renderItem={renderItem}
        contentContainerStyle={{
          gap: 18,
          paddingBottom: 16,
        }}
        scrollEnabled={scrollEnabled}
        numColumns={numColumns}
      />
    </View>
  );
};

export default GroupListCheck;
