import {useNavigation, useRoute} from '@react-navigation/native';

import {isEmpty} from 'lodash';
import React, {useEffect, useRef, useState} from 'react';
import {useTranslation} from 'react-i18next';
import {TouchableOpacity, View} from 'react-native';
import {KeyboardAwareScrollView} from 'react-native-keyboard-aware-scroll-view';
import {SafeAreaView} from 'react-native-safe-area-context';
import {
  ITypeParties,
  mapFullName,
  mapLabelEmail,
  mapLabelPhone,
  mapRoleRecipientToUi,
} from '../confirm-info-document/helper';
import {renderTitle, typeRoleRecipients} from './helper';
import styles from './styles';
import {
  IRecipientsByIdentify,
  ISubItemIdentify,
} from '../../../../model/interface/envelope.interface';
import Regex from '../../../../utils/Regex';
import Toast from 'react-native-toast-message';
import {NavigationName} from '../../../../constants';
import TextCM from '../../../../components/Text';
import {IconBlackDown, IconBlackUp} from '../../../../assets/images';
import HeaderCM from '../../../../components/Header/HeaderCM';
import ButtonCM from '../../../../components/Button';
import {useDocumentServices} from '../../../../hook/apiHook/useApi';
import TextFieldCM from '../../../../components/TextField';

const ItemDetails = ({
  item,
  onChangeContact,
  handleChangeSttSubItem,
  handleChangeTypeNotification,
  errors,
  notificationErrors,
  toggleModal,
  listNotificationType,
  setListNotificationType,
}: {
  item: IRecipientsByIdentify;
  onChangeContact: (id: string, field: string, value: string) => void;
  handleChangeTypeNotification: (id: string, value: string) => void;
  handleChangeSttSubItem: (id: string, value: string) => void;
  errors: {[key: string]: string};
  notificationErrors: {[key: string]: string};
  toggleModal: () => void;
  listNotificationType: any;
  setListNotificationType: (newData: []) => void;
}) => {
  const {t} = useTranslation();

  return (
    <View style={styles.ctnMainSubItem}>
      <View style={styles.ctnTextInput}>
        <TextFieldCM
          isRequired
          label={mapFullName(item.role)}
          value={item.contact.name}
          placeholder={t('eContract.DC.NameOfReviewer')}
          onChangeText={newName =>
            onChangeContact(item.id, 'name', newName.trimStart())
          }
          inputContainerStyle={styles.bgrWhite}
          errorMessage={errors[`${item.id}_name`] || ''}
        />
        <TextFieldCM
          isRequired
          label={mapLabelEmail(item.role)}
          value={item.contact.email}
          placeholder={t('eContract.DC.EmailReviewer')}
          onChangeText={newEmail =>
            onChangeContact(item.id, 'email', newEmail.trimStart())
          }
          inputContainerStyle={styles.bgrWhite}
          errorMessage={errors[`${item.id}_email`] || ''}
          keyboardType="email-address"
        />
        <TextFieldCM
          isRequired={true}
          label={mapLabelPhone(item.role)}
          value={item.contact.phone}
          placeholder={t('eContract.DC.PhoneReviewer')}
          onChangeText={newPhone =>
            onChangeContact(item.id, 'phone', newPhone.trimStart())
          }
          inputContainerStyle={styles.bgrWhite}
          keyboardType="number-pad"
          errorMessage={errors[`${item.id}_phone`] || ''}
        />
      </View>
    </View>
  );
};

const IdentifySignatory = () => {
  const {t} = useTranslation();
  const route = useRoute<any>();
  const dataRoute: any = route.params.data;
  const templateId: any = route.params.templateId ?? '';
  const dataFormUpdate: any = route.params.dataFormUpdate ?? [];

  const [data, setData] = useState(dataRoute.parties);
  const navigation = useNavigation<any>();
  const isInitialMount = useRef(true);

  const [expandedItems, setExpandedItems] = useState<any>({});
  const [loadingSubmit, setLoadingSubmit] = useState<boolean>(false);
  const [listNotificationType, setListNotificationType] = useState<any>({});
  const [errors, setErrors] = useState<{[key: string]: string}>({});
  const [notificationErrors, setNotificationErrors] = useState<{
    [key: string]: string;
  }>({});
  const [showModal, setShowModal] = useState<{[key: string]: boolean}>({});

  const DocumentServices = useDocumentServices();

  useEffect(() => {
    if (isInitialMount.current) {
      const initialErrors: {[key: string]: string} = {};
      data.forEach((mainItem: ISubItemIdentify) => {
        if (!mainItem.name) {
          initialErrors[`${mainItem.id}_partyName`] = t('eContract.CM.RequireField');
        }
        mainItem.recipients.forEach((recipient: IRecipientsByIdentify) => {
          if (!recipient.contact.name) {
            initialErrors[`${recipient.id}_name`] = t('eContract.CM.RequireField');
          }
          if (!recipient.contact.email) {
            initialErrors[`${recipient.id}_email`] = t('eContract.CM.RequireField');
          }
          if (!recipient.contact.phone) {
            initialErrors[`${recipient.id}_phone`] = t('eContract.CM.RequireField');
          }
        });
      });
      setErrors(initialErrors);
      isInitialMount.current = false;
    }
  }, [data, t]);

  const toggleItem = (id: string) => {
    setExpandedItems((prevState: any) => ({
      ...prevState,
      [id]: !prevState[id],
    }));
  };
  const handleChangeContact = (id: string, field: string, value: string) => {
    const newData = data.map((mainItem: ISubItemIdentify) => {
      return {
        ...mainItem,
        name:
          field === 'partyName' && id === mainItem.id ? value : mainItem.name,
        recipients: mainItem.recipients.map((recipient: any) => {
          if (recipient.id === id) {
            return {
              ...recipient,
              contact: {
                ...recipient.contact,
                [field]: value,
              },
            };
          }
          return recipient;
        }),
      };
    });
    setData(newData);
    setErrors(prevErrors => {
      const newErrors = {...prevErrors};
      if (field === 'email') {
        if (!value) {
          newErrors[`${id}_${field}`] = t('eContract.CM.RequireField');
        } else if (!Regex.FORMAT_EMAIL.test(value)) {
          newErrors[`${id}_${field}`] = t('eContract.CM.EmailNotCorrectFormat');
        } else {
          delete newErrors[`${id}_${field}`];
        }
      } else if (field === 'phone') {
        if (!value) {
          newErrors[`${id}_${field}`] = t('eContract.CM.RequireField');
        } else if (!Regex.REGEX_PHONE_NUMBER_9.test(value)) {
          newErrors[`${id}_${field}`] = t('eContract.CM.wrongPhoneNumber');
        } else {
          delete newErrors[`${id}_${field}`];
        }
      } else if (!value) {
        newErrors[`${id}_${field}`] = t('eContract.CM.RequireField');
      } else {
        delete newErrors[`${id}_${field}`];
      }
      return newErrors;
    });
  };

  const handleChangeSttSubItem = (id: string, value: string) => {
    const newData = data.map((mainItem: ISubItemIdentify) => {
      return {
        ...mainItem,
        recipients: mainItem.recipients.map((recipient: any) => {
          if (recipient.id === id) {
            return {
              ...recipient,
              order: isEmpty(value) ? null : +value,
            };
          }
          return recipient;
        }),
      };
    });
    setData(newData);
  };

  const handleChangeTypeNotification = (id: string, value: string) => {
    const newData = data.map((mainItem: ISubItemIdentify) => {
      return {
        ...mainItem,
        recipients: mainItem.recipients.map((recipient: any) => {
          if (recipient.id === id) {
            return {
              ...recipient,
              notifyTypes: value,
            };
          }
          return recipient;
        }),
      };
    });
    setData(newData);
    if (value.length === 0) {
      setNotificationErrors(prevErrors => ({
        ...prevErrors,
        [id]: t('eContract.CM.RequireField'),
      }));
    } else {
      setNotificationErrors(prevErrors => {
        const newErrors = {...prevErrors};
        delete newErrors[id];
        return newErrors;
      });
    }
  };

  const toggleModal = (id: string) => {
    setShowModal((prevState: any) => ({
      ...prevState,
      [id]: !prevState[id],
    }));
  };

  const handleOnPress = (id: string, data: any) => {
    setListNotificationType((prevState: any) => ({
      ...prevState,
      [id]: data,
    }));
    handleChangeTypeNotification(id, data);
  };

  const onSubmit = async () => {
    try {
      setLoadingSubmit(true);
      const listData: any[] = [];
      data.forEach((mainItem: ISubItemIdentify) => {
        listData.push({
          id: mainItem.id,
          type: 'p',
          value: mainItem.name,
        });
        mainItem.recipients.forEach(recipient => {
          listData.push({
            id: recipient.id,
            type: 'r',
            value: recipient.contact.name,
          });
          listData.push({
            id: recipient.id,
            type: 'm',
            value: recipient.contact.email,
          });
          listData.push({
            id: recipient.id,
            type: 'phone',
            value: recipient.contact.phone,
          });
        });
      });

      const body = {
        datas: [[...dataFormUpdate, ...listData]],
        templateId: templateId,
      };

      const response = await DocumentServices.createContractTemplate(body);
      if (response?.status === 202) {
        Toast.show({
          type: 'success',
          text1: t('eContract.CM.successCreate'),
        });
        navigation.navigate(NavigationName.DocumentScreen);
      } else {
        Toast.show({
          type: 'error',
          text1: t('eContract.CM.errorExist'),
        });
      }
    } catch (error) {
    } finally {
      setLoadingSubmit(false);
    }
  };
  const onSaveData = () => {
    navigation.goBack();
  };

  const renderItem = (items: ISubItemIdentify) => {
    const sortByRole = (a: IRecipientsByIdentify, b: IRecipientsByIdentify) => {
      const roleOrder = [
        typeRoleRecipients.coordinator,
        typeRoleRecipients.reviewer,
        typeRoleRecipients.signer,
        typeRoleRecipients.stamper,
        typeRoleRecipients.cc,
      ];
      return roleOrder.indexOf(a.role) - roleOrder.indexOf(b.role);
    };

    const recipientsArray = Array.isArray(items.recipients)
      ? items.recipients
      : [];

    const sortedRecipients: IRecipientsByIdentify[] = [...recipientsArray].sort(
      sortByRole,
    );

    const groupedRecipients = sortedRecipients.reduce(
      (groups, recipient) => {
        if (!groups[recipient.role]) {
          groups[recipient.role] = {count: 0, recipients: []};
        }
        groups[recipient.role].recipients.push(recipient);
        groups[recipient.role].count += 1;
        return groups;
      },
      {} as {
        [role: string]: {count: number; recipients: IRecipientsByIdentify[]};
      },
    );

    const groupedRecipientsArray = Object.entries(groupedRecipients).map(
      ([role, data]) => ({
        role,
        count: data.count,
        recipients: data.recipients,
      }),
    );

    return (
      <View key={items.id}>
        <View style={styles.ctnMainItem}>
          <View style={[styles.txtHeader, styles.ctnHeaderOzganization]}>
            <View style={{flex: 1, rowGap: 6}}>
              {renderTitle(items)}
              {items.type !== ITypeParties.individual && (
                <TextFieldCM
                  label={t('eContract.SU.Organization')}
                  isRequired
                  value={items.name}
                  onChangeText={name =>
                    handleChangeContact(items.id, 'partyName', name.trimStart())
                  }
                  errorMessage={errors[`${items.id}_partyName`] || ''}
                />
              )}
            </View>
          </View>
          {groupedRecipientsArray.map((group: any) => {
            const item = group.recipients[0];
            return (
              <View key={item.id} style={styles.ctnMainItemElement}>
                <TouchableOpacity onPress={() => toggleItem(item.id)}>
                  <View style={styles.ctnMainTitleItem}>
                    <View style={styles.ctnTitleItem}>
                      {mapRoleRecipientToUi(item.role).icon}
                      <TextCM style={styles.txtTitleItem}>
                        {`${mapRoleRecipientToUi(item.role).label} (${
                          group.count
                        })`}
                      </TextCM>
                    </View>
                    {expandedItems[item.id] ? (
                      <IconBlackUp width={14} height={12} />
                    ) : (
                      <IconBlackDown width={14} height={12} />
                    )}
                  </View>
                </TouchableOpacity>
                {expandedItems[item.id] && (
                  <View>
                    {group.recipients.map(
                      (recipient: IRecipientsByIdentify) => (
                        <ItemDetails
                          key={recipient.id}
                          item={recipient}
                          onChangeContact={handleChangeContact}
                          handleChangeSttSubItem={handleChangeSttSubItem}
                          handleChangeTypeNotification={
                            handleChangeTypeNotification
                          }
                          errors={errors}
                          notificationErrors={notificationErrors}
                          toggleModal={() => toggleModal(recipient.id)}
                          listNotificationType={
                            listNotificationType[recipient.id]
                          }
                          setListNotificationType={data =>
                            handleOnPress(recipient.id, data)
                          }
                        />
                      ),
                    )}
                  </View>
                )}
              </View>
            );
          })}
        </View>
        <View style={styles.line} />
      </View>
    );
  };

  return (
    <SafeAreaView edges={['bottom']} style={styles.ctnMain}>
      <HeaderCM title={t('eContract.DC.DocumentTemplate.TxtCreateSingle')} />
      <View style={styles.contain}>
        <KeyboardAwareScrollView showsVerticalScrollIndicator={false}>
          <View style={styles.body}>
            <View style={styles.subHeader}>
              <TextCM style={styles.txtTitle}>
                {t('eContract.DC.IdentifyTheSigner')}
              </TextCM>
            </View>
            <View style={styles.line} />
            {data.map(renderItem)}
          </View>
        </KeyboardAwareScrollView>
      </View>
      <View style={styles.footer}>
        <ButtonCM
          label={t('eContract.CM.BtnBack')}
          type="white"
          onPress={onSaveData}
          style={styles.btnFooter}
        />
        <ButtonCM
          disabled={isEmpty(errors) ? false : true}
          label={t('eContract.DC.DocumentTemplate.TxtCreateSingle')}
          onPress={onSubmit}
          style={styles.btnFooter}
          loading={loadingSubmit}
        />
      </View>
    </SafeAreaView>
  );
};

export default IdentifySignatory;
