import {BASE_URL, BASE_URL_EACCOUNT} from './httpClient';
import { IImageDigitalSignature, IImageSignature } from './interface';

export const createAccountServices = (fetchRequest: any) => ({
  async postUpdateAvatar(body: any) {
    try {
      const endPoint = '/services/uaa/api/account/avatar';
      const res = await fetchRequest({
        url: `${BASE_URL}${endPoint}`,
        method: 'POST',
        headers: {
          'Content-Type': 'multipart/form-data',
        },
        body,
      });
      return Promise.resolve(res.data);
    } catch (error) {
      console.error('Error postUpdateAvatar:', error);
      return Promise.reject(error);
    }
  },
  async deleteAvatar() {
    try {
      const endPoint = '/services/uaa/api/account/avatar';
      const res = await fetchRequest({
        url: `${BASE_URL}${endPoint}`,
        method: 'DELETE',
        headers: {
          'Content-Type': 'application/json',
        },
        typeOfResponse: 'text',
      });
      return Promise.resolve(res.data);
    } catch (error) {
      console.error('Error deleteAvatar:', error);
      return Promise.reject(error);
    }
  },
  async postUpdateInfo(body: any) {
    try {
      const endPoint = '/services/uaa/api/account';
      const res = await fetchRequest({
        url: `${BASE_URL}${endPoint}`,
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify(body),
        typeOfResponse: 'text',
      });
      return Promise.resolve(res);
    } catch (error) {
      console.error('Error postUpdateInfo:', error);
      return Promise.reject(error);
    }
  },
  async fetchTwoFactorState(email: string) {
    try {
      const endPoint = `services/uaa/api/user/is-active-two-factor/${email}`;
      const res = await fetchRequest({
        url: `${BASE_URL}/${endPoint}`,
        method: 'GET',
        headers: {
          'Content-Type': 'application/json',
        },
      });
      return Promise.resolve(res);
    } catch (error) {
      console.error('Error fetchTwoFactorState:', error);
      return Promise.reject(error);
    }
  },
  async turnOffTwoFactor(body: any) {
    try {
      const endPoint = `services/uaa/api/p/user-secrect-codes/active-two-factor-app`;
      const res = await fetchRequest({
        url: `${BASE_URL}/${endPoint}`,
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body,
      });
      return Promise.resolve(res.josn());
    } catch (error) {
      console.error('Error turnOffTwoFactor:', error);
      return Promise.reject(error);
    }
  },
  async listImageSignature(body: {name: string}): Promise<IImageSignature[]> {
    try {
      const endpoint = '/services/uaa/api/account/signature-eaccount-search';
      const resp = await fetchRequest({
        url: BASE_URL_EACCOUNT + endpoint,
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify(body),
      });
      return Promise.resolve(resp.data);
    } catch (error) {
      console.error('err listImageSignature', error);
      return Promise.reject(error);
    }
  },
  async updateImageSignature(data: {id?: number; data: any}) {
    try {
      const endpoint =
        '/services/uaa/api/account/signature-eaccount/' +
        `${data.id ? data.id : ''}`;
      const resp = await fetchRequest({
        url: BASE_URL_EACCOUNT + endpoint,
        method: data.id ? 'PUT' : 'POST',
        headers: {
          'Content-Type': 'multipart/form-data',
        },
        body: data.data,
        typeOfResponse: data.id ? '' : 'json',
      });
      return Promise.resolve(resp);
    } catch (error) {
      console.error('err updateImageSignature', error);
      return Promise.reject(error);
    }
  },
  async previewImageDesign(recipient: any) {
    try {
      const endpoint =
        '/services/envelope/api/p/envelope/multimediaProcessing/image/previewVisibleDesign/1';
      const resp = await fetchRequest({
        url: BASE_URL + endpoint,
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify(recipient),
        typeOfResponse: 'text',
      });
      return Promise.resolve(resp);
    } catch (error) {
      console.error('err previewImageDesign', error);
      return Promise.reject(error);
    }
  },
  async deleteImageSignature(id: number) {
    try {
      const endpoint = '/services/uaa/api/account/signature-eaccount/' + id;
      const resp = await fetchRequest({
        url: BASE_URL_EACCOUNT + endpoint,
        method: 'DELETE',
        headers: {
          'Content-Type': 'application/json',
        },
        typeOfResponse: 'text',
      });
      return Promise.resolve(resp);
    } catch (error) {
      console.error('err deleteImageSignature', error);
      return Promise.reject(error);
    }
  },
  async listImageDigitalSignature(body: {
    name: string;
  }): Promise<IImageDigitalSignature[]> {
    try {
      const endpoint =
        '/services/uaa/api/account/digital-signature-eaccount-search';
      const resp = await fetchRequest({
        url: BASE_URL_EACCOUNT + endpoint,
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify(body),
      });
      return Promise.resolve(resp.data);
    } catch (error) {
      console.error('err listImageDigitalSignature', error);
      return Promise.reject(error);
    }
  },
  async updateImageDigitalSignature(data: {id?: number; data: any}) {
    try {
      const endpoint =
        '/services/uaa/api/account/digitalSignature-eaccount/' +
        `${data.id ? data.id : ''}`;
      const resp = await fetchRequest({
        url: BASE_URL_EACCOUNT + endpoint,
        method: data.id ? 'PUT' : 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify(data.data),
      });
      return Promise.resolve(resp);
    } catch (error) {
      console.error('err updateImageDigitalSignature', error);
      return Promise.reject(error);
    }
  },
  async deleteImageDigitalSignature(id: number) {
    try {
      const endpoint = '/services/uaa/api/account/digitalSignature-eaccount/';
      const resp = await fetchRequest({
        url: BASE_URL_EACCOUNT + endpoint + id,
        method: 'DELETE',
        headers: {
          'Content-Type': 'application/json',
        },
        typeOfResponse: 'text',
      });
      return Promise.resolve(resp);
    } catch (error) {
      console.error('err deleteImageDigitalSignature', error);
      return Promise.reject(error);
    }
  },
  async postUpdateOrganization(body: any) {
    try {
      const endpoint = '/services/uaa/api/organizations/orgu';
      const resp = await fetchRequest({
        url: BASE_URL + endpoint,
        method: 'PUT',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify(body),
      });
      return Promise.resolve(resp.data);
    } catch (error) {
      console.error('err postUpdateOrganization', error);
      return Promise.reject(error);
    }
  },
  async clearBackground(imageBase64: string) {
    try {
      const endpoint = '/services/envelope/api/p/envelope/multimediaProcessing/image/focusBackground/autoFocus';
      const resp = await fetchRequest({
        url: BASE_URL + endpoint,
        method: 'POST',
        headers: {
          'Content-Type': 'text/plain',
        },
        body: imageBase64,
        typeOfResponse: 'text',
      });
      console.log("clear background xong", resp);
      return Promise.resolve(resp);
    } catch (error) {
      console.error('err clearBackground', error);
      return Promise.reject(error);
    }
  },
});
