import {View, Text, KeyboardTypeOptions, StyleProp, ViewStyle} from 'react-native';
import React, {useState} from 'react';
import {
  Control,
  Controller,
  FieldValues,
  useFormContext,
} from 'react-hook-form';
import {isEmpty, isUndefined} from 'lodash';
import TextFieldCM from '../../../../components/TextField';

type Props = {
  controlName: string;
  label: string;
  isRequired?: boolean;
  multiline?: boolean;
  maxLength?: number;
  onPassBlur?: (value: any) => void;
  isDisabled?: boolean;
  keyboardType?: KeyboardTypeOptions;
  errorContainerStyle?: StyleProp<ViewStyle>;
};

const YupTextField = ({
  controlName,
  label,
  isRequired,
  multiline,
  maxLength,
  onPassBlur,
  isDisabled,
  keyboardType,
  errorContainerStyle,
}: Props) => {
  const {
    control,
    formState: {errors},
  } = useFormContext();

  const [scrollEnabled, setScrollEnabled] = useState(false);

  const handleMultiline = (scrollEnabled: boolean) => () => {
    if (multiline) {
      setTimeout(() => {
        setScrollEnabled(scrollEnabled);
      }, 1000);
    }
  };

  return (
    <View>
      <Controller
        control={control}
        name={controlName}
        render={({field: {onChange, onBlur, value}}) => {
          const handleBlur = () => {
            onBlur();
            if (!isUndefined(onPassBlur)) {
              onPassBlur(value);
            }
            handleMultiline(false)();
          };
          return (
            <TextFieldCM
              isDisabled={isDisabled}
              label={label}
              placeholder={label}
              isRequired={isRequired}
              value={value}
              onBlur={handleBlur}
              onChangeText={onChange}
              multiline={multiline}
              maxLength={maxLength}
              errorMessage={errors[controlName]?.message as string}
              scrollEnabled={multiline ? scrollEnabled : undefined}
              onFocus={handleMultiline(true)}
              keyboardType={keyboardType}
              errorContainerStyle={errorContainerStyle}
            />
          );
        }}
      />
    </View>
  );
};

export default YupTextField;
