import {
  View,
  TouchableOpacity,
  ViewStyle,
  TextStyle,
  FlatList,
} from 'react-native';
import React from 'react';
import styles from './styles';
import {IconCheckedRadio, IconRadio} from '../../assets/images';
import TextCM from '../Text';
import {useTranslation} from 'react-i18next';

export type GroupData = {
  id: string | number;
  label: string;
};

type Props = {
  data: GroupData[];
  currentValue?: GroupData;
  onPressData: (item: GroupData) => void;
  containerStyle?: ViewStyle;
  itemStyle?: ViewStyle;
  labelStyle?: TextStyle;
  numColumns?: number;
  scrollEnabled?: boolean;
  renderLabel?: (item: GroupData) => React.ReactNode;
};
const GroupRadio = ({
  data,
  currentValue,
  onPressData,
  containerStyle,
  itemStyle,
  labelStyle,
  numColumns = 1,
  scrollEnabled = false,
  renderLabel,
}: Props) => {
  const checkSelected = (item: GroupData) => {
    return item.id === currentValue?.id;
  };

  const {t} = useTranslation();

  const onPressItem = (item: GroupData) => {
    if (checkSelected(item)) return;
    onPressData(item);
  };

  const renderItem = ({item}: {item: GroupData}) => {
    return (
      <TouchableOpacity
        key={item.id}
        style={[styles.viewItem, itemStyle]}
        onPress={() => {
          onPressItem(item);
        }}>
        {checkSelected(item) ? (
          <IconCheckedRadio width={24} height={24} />
        ) : (
          <IconRadio width={24} height={24} />
        )}
        {renderLabel ? (
          renderLabel(item)
        ) : (
          <TextCM style={[styles.txtName, labelStyle]}>{t(item.label)}</TextCM>
        )}
      </TouchableOpacity>
    );
  };

  return (
    <View style={[styles.container, containerStyle]}>
      <FlatList
        data={data}
        keyExtractor={item => item.id.toString()}
        renderItem={renderItem}
        contentContainerStyle={{
          gap: 18,
        }}
        scrollEnabled={scrollEnabled}
        numColumns={numColumns}
      />
    </View>
  );
};

export default GroupRadio;
