import React, {useEffect, useState} from 'react';
import {useTranslation} from 'react-i18next';
import {KeyboardAvoidingView, Modal, TouchableOpacity} from 'react-native';
import {useSafeAreaInsets} from 'react-native-safe-area-context';
import styles from './styles';
import {useAppDispatch, useAppSelector} from '../../../../hook/useRedux';
import {accountActions} from '../../../../redux/slices';
import TextCM from '../../../../components/Text';
import {View as ViewCM} from 'react-native';
import {IconBlackLeftArrow} from '../../../../assets/images';
import {SizeDP} from '../../../../constants/Size';
import TextFieldCM from '../../../../components/TextField';
import ButtonCM from '../../../../components/Button';
import Toast from 'react-native-toast-message';
import {useAccountServices} from '../../../../hook/apiHook/useApi';

type Props = {
  isVisible: boolean;
  onClose: () => void;
};

const MAX_LENGTH = 200;
const MAX_LENGTH_30 = 30;

const ModalUpdateOrganization = ({isVisible, onClose}: Props) => {
  const {t} = useTranslation();
  const dispatch = useAppDispatch();
  const insets = useSafeAreaInsets();

  const user = useAppSelector(state => state.account.dataAccount);

  const organization = user?.organization || {};

  const accountServices = useAccountServices();

  const [shortName, setShortName] = useState(organization.acName);
  const [organizationCode, setOrganizationCode] = useState(
    organization.orgCode,
  );

  useEffect(() => {
    setShortName(organization.acName);
    setOrganizationCode(organization.orgCode);
  }, [organization, isVisible]);

  const onPressSave = async () => {
    const body = {
      address: null,
      id: organization.id,
      orgAcronym: shortName.trim(),
      orgCode: organizationCode.trim(),
      orgName: organization.name,
      taxCode: organization.taxCode,
      type: organization.type,
      block: organization.blocked,
      orgIn: user.orgIn,
    };
    try {
      const data = await accountServices.postUpdateOrganization(body);
      console.log('call api xong: ', data);
      Toast.show({
        text1: t('eContract.AI.messageValidate.updateSuccess'),
        type: 'success',
      });
      dispatch(accountActions.fetchAccount());
      onClose();
    } catch (error) {
      onClose();
      Toast.show({
        type: 'error',
        text1: t('eContract.CM.TxtSystemError'),
      });
    }
  };

  return (
    <Modal animationType="fade" transparent visible={isVisible}>
      <ViewCM style={styles.ctnContainer}>
        <ViewCM style={styles.ctnTop} onTouchEnd={onClose} />
        <KeyboardAvoidingView
          behavior={'padding'}
          keyboardVerticalOffset={-insets.bottom}>
          <ViewCM style={[styles.ctnContent, {paddingBottom: insets.bottom}]}>
            <ViewCM style={styles.viewHeader}>
              <TouchableOpacity onPress={onClose}>
                <IconBlackLeftArrow width={SizeDP(14)} height={SizeDP(16)} />
              </TouchableOpacity>
              <TextCM style={styles.txtTitle}>
                {t('eContract.AI.TxtOrganizationInfo')}
              </TextCM>
              <ViewCM />
            </ViewCM>
            <ViewCM style={styles.viewBody}>
              <TextFieldCM
                label={t('eContract.AI.TxtCompanyName')}
                value={organization.name}
                isDisabled
              />
              <TextFieldCM
                label={t('eContract.AI.TxtTaxCode')}
                value={organization.taxCode}
                isDisabled
              />
              <TextFieldCM
                label={t('eContract.AI.TxtShortName')}
                value={shortName}
                onChangeText={setShortName}
                maxLength={MAX_LENGTH}
              />
              <TextFieldCM
                label={t('eContract.AI.TxtOrganizationCode')}
                value={organizationCode}
                onChangeText={setOrganizationCode}
                maxLength={MAX_LENGTH_30}
              />
            </ViewCM>
            <ViewCM style={styles.footer}>
              <ButtonCM label={t('eContract.CM.TxtSave')} onPress={onPressSave} />
            </ViewCM>
          </ViewCM>
        </KeyboardAvoidingView>
      </ViewCM>
    </Modal>
  );
};

export default ModalUpdateOrganization;
