export const getListGeneralSettings = (isAdmin: boolean) => {
  return isAdmin
    ? LIST_CATEGORY_GENERAL_SETTING
    : LIST_CATEGORY_GENERAL_SETTING.filter(
        item => item.type !== IGeneralSetting.configSecurity,
      );
};
